/// <summary>
/// Carries message identifiers, metadata and the target of an outbound document upload.
/// </summary>
[DataContract]
public final class OMGOutboundUploadBussEventContract extends BusinessEventsWorkflowDataContract
{
    private OMGMessageTypeId messageTypeId;
    private OMGMessageGUID messageGUID;
    private DataAreaId dataAreaId;
    private UtcDateTime CreatedDateTime;
    private str sourceEnvironment;
    private str msgProperties;
    private URL targetUri;

}

Method.Source:
[DataMember('MessageTypeId'), BusinessEventsDataMember('MessageTypeId')]
public OMGMessageTypeId parmMessageTypeId(OMGMessageTypeId _messageTypeId = messageTypeId)
{
    messageTypeId = _messageTypeId;
    return messageTypeId;
}

[DataMember('MessageGUID'), BusinessEventsDataMember('CorrelationId')]
public OMGMessageGUID parmMessageGUID(OMGMessageGUID _messageGUID = messageGUID)
{
    messageGUID = _messageGUID;
    return messageGUID;
}

[DataMember('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

[DataMember('CreatedDateTime'), BusinessEventsDataMember('MessageCreatedDateTime')]
public UtcDateTime parmCreatedDateTime(UtcDateTime _createdDateTime = createdDateTime)
{
    createdDateTime = _createdDateTime;
    return createdDateTime;
}

[DataMember('SourceEnvironment'), BusinessEventsDataMember('MessageSourceEnvironment')]                               
public str parmSourceEnvironment(str _sourceEnvironment = sourceEnvironment)
{
    sourceEnvironment = _sourceEnvironment;
    return sourceEnvironment;
}

[DataMember('MsgProperties'), BusinessEventsDataMember('MessageProperties')]
public str parmMsgProperties(str _msgProperties = msgProperties)
{
    msgProperties = _msgProperties;
    return msgProperties;
}

/// <summary>
/// Gets or sets the URI of the uploaded blob, without query string or SAS token.
/// </summary>
/// <param name = "_targetUri">The blob URI.</param>
/// <returns>The blob URI.</returns>
[DataMember('TargetUri'), BusinessEventsDataMember("@OMG:TargetUriDescr")]
public URL parmTargetUri(URL _targetUri = targetUri)
{
    targetUri = _targetUri;
    return targetUri;
}
